SELECT table_id, table_name, table_code, data_source_id, tenant_id
FROM bt_data_table
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND table_id = #{tableId}

SELECT table_id, table_name, table_code, data_source_id, tenant_id
FROM bt_data_table
WHERE status_cd = '00A'
  AND tenant_id = #{query.tenantId}

  AND data_source_id = #{query.dataSourceId}


  AND (table_name LIKE #{query.tableName}
      OR table_code LIKE #{query.tableName}
      )

ORDER BY updated_time DESC
